import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int batch, int N, float eps)
{
    int b = blockIdx.x;
    if (b >= batch) return;

    // CuTe tensors over the flattened (batch, N) view
    Tensor gX = make_tensor(make_gmem_ptr(x), make_shape(batch, N), make_stride(N, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y), make_shape(batch, N), make_stride(N, 1));
    Tensor gW = make_tensor(make_gmem_ptr(weight), make_shape(N), make_stride(1));
    Tensor gB = make_tensor(make_gmem_ptr(bias), make_shape(N), make_stride(1));

    Tensor xRow = gX(b, _);
    Tensor yRow = gY(b, _);

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sqsum = sdata + nthreads;

    float local_sum = 0.f;
    for (int i = tid; i < N; i += nthreads) {
        local_sum += xRow(i);
    }
    s_sum[tid] = local_sum;
    __syncthreads();
    for (int stride = nthreads / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid + stride];
        }
        __syncthreads();
    }
    __shared__ float mean_s;
    __shared__ float invstd_s;
    if (tid == 0) {
        mean_s = s_sum[0] / (float)N;
    }
    __syncthreads();
    float mean = mean_s;
    float local_sqdiff = 0.f;
    for (int i = tid; i < N; i += nthreads) {
        float d = xRow(i) - mean;
        local_sqdiff += d * d;
    }
    s_sqsum[tid] = local_sqdiff;
    __syncthreads();
    for (int stride = nthreads / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sqsum[tid] += s_sqsum[tid + stride];
        }
        __syncthreads();
    }
    if (tid == 0) {
        float var = s_sqsum[0] / (float)N;
        invstd_s = rsqrtf(var + eps);
    }
    __syncthreads();
    float invstd = invstd_s;

    for (int i = tid; i < N; i += nthreads) {
        float v = xRow(i);
        float norm = (v - mean) * invstd;
        yRow(i) = norm * gW(i) + gB(i);
    }
}

torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "expect float32 tensor");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    int64_t N = w_c.numel();
    int64_t total = x_c.numel();
    TORCH_CHECK(total % N == 0, "input size must be divisible by normalized_shape numel");
    int batch = (int)(total / N);

    auto y = torch::empty_like(x_c);

    int threads = 256;
    dim3 grid(batch);
    dim3 block(threads);
    size_t shmem = 2 * threads * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_layernorm_kernel<<<grid, block, shmem, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        y.data_ptr<float>(),
        batch, (int)N, (float)eps);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE layernorm launch failed");
    return y;
}
"""

cute_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Layer Normalization using a custom CuTe/CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple) -> None:
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x_cuda = x.cuda() if not x.is_cuda else x
        weight = self.weight.to(device=x_cuda.device, dtype=x_cuda.dtype)
        bias = self.bias.to(device=x_cuda.device, dtype=x_cuda.dtype)
        return self._ext.cute_layernorm(x_cuda, weight, bias, self.eps)

